import math
def priority(task, state, k=1.0, m=2.0, b=0.5, C=1e6):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    if slack >= 0.0:
        atc = tier * task.weight / est * math.exp(-slack / (k * mean_est))
        return atc * (1.0 + b * wait / est)
    else:
        return -C - est

def priority(task, state, late_penalty=1e9, premium_bonus=0.0, risk_boost=0.0, risk_window=2.0):
    now = state.now
    est = max(task.estimated_runtime, 1e-6)
    due = task.due
    score = -due
    if task.tenant == 'premium':
        score += premium_bonus
    if now >= due:
        score -= late_penalty
    else:
        slack = due - now - est
        if slack < 0.0:
            mean = max(state.mean_est, 1e-6)
            risk = min(-slack, risk_window * mean)
            score += risk_boost * risk / mean
    return score

